<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;color:#172033;font-size:12px}h1{color:#2563eb}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border-bottom:1px solid #ddd;padding:8px;text-align:left}.total{text-align:right;font-size:14px;font-weight:bold}</style></head><body><h1>CleanFlow Laundry OS</h1><p><strong>Invoice #:</strong> {{ $invoice->invoice_number }}<br><strong>Order #:</strong> {{ $invoice->order->order_number }}<br><strong>Date:</strong> {{ $invoice->issued_at->format('Y-m-d') }}</p><p><strong>Customer:</strong> {{ $invoice->order->customer->name }}<br><strong>Phone:</strong> {{ $invoice->order->phone }}<br><strong>Address:</strong> {{ $invoice->order->pickup_address }}</p><table><thead><tr><th>Service</th><th>Quantity</th><th>Unit price</th><th>Subtotal</th></tr></thead><tbody>@foreach($invoice->order->items as $item)<tr><td>{{ $item->service->name }}</td><td>{{ $item->quantity }}</td><td>{{ number_format($item->unit_price,2) }}</td><td>{{ number_format($item->subtotal,2) }}</td></tr>@endforeach</tbody></table><p class="total">Total Amount: {{ number_format($invoice->order->total_amount,2) }} Birr</p><p>Payment method: {{ strtoupper($invoice->payment?->payment_method ?? 'pending') }}<br>Payment status: {{ strtoupper($invoice->order->payment_status) }}</p></body></html>
